import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';

type Faculty = {
  id: string;
  name: string;
  email: string;
  department: string;
  position: string;
};

export default function FacultySection() {
  const [faculty, setFaculty] = useState<Faculty[]>([]);

  useEffect(() => {
    const fetchFaculty = async () => {
      try {
        const response = await fetch('http://localhost:5000/api/faculty');
        const data = await response.json();
        setFaculty(data);
      } catch (error) {
        console.error('Error fetching faculty:', error);
      }
    };
    fetchFaculty();
  }, []);
  const [formData, setFormData] = useState<Omit<Faculty, 'id'>>({ 
    name: '', 
    email: '', 
    department: '',
    position: ''
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch('http://localhost:5000/api/faculty', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });
      const newFaculty = await response.json();
      setFaculty([...faculty, newFaculty]);
      setFormData({ name: '', email: '', department: '', position: '' });
    } catch (error) {
      console.error('Error adding faculty:', error);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  return (
    <div className="container mt-5">
      <h1 className="mb-4 text-primary">Faculty Management</h1>
      <Link to="/" className="btn btn-secondary mb-4">Back to Home</Link>
      
      <form onSubmit={handleSubmit} className="mb-4">
        <div className="form-group mb-3">
          <input
            type="text"
            name="name"
            className="form-control"
            placeholder="Faculty Name"
            value={formData.name}
            onChange={handleChange}
            required
          />
        </div>
        <input
          type="email"
          name="email"
          placeholder="Email"
          value={formData.email}
          onChange={handleChange}
          required
        />
        <input
          type="text"
          name="department"
          placeholder="Department"
          value={formData.department}
          onChange={handleChange}
          required
        />
        <input
          type="text"
          name="position"
          placeholder="Position"
          value={formData.position}
          onChange={handleChange}
          required
        />
        <button type="submit" className="btn btn-success">Add Faculty</button>
      </form>

      <div className="card border-primary">
        <div className="card-header bg-primary text-white">
          <h2>Faculty Records</h2>
        </div>
        <div className="card-body">
          {faculty.length > 0 ? (
            <table className="table table-striped table-hover">
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Email</th>
                  <th>Department</th>
                  <th>Position</th>
                </tr>
              </thead>
              <tbody>
                {faculty.map(faculty => (
                  <tr key={faculty.id}>
                    <td>{faculty.name}</td>
                    <td>{faculty.email}</td>
                    <td>{faculty.department}</td>
                    <td>{faculty.position}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <p className="text-muted">No faculty added yet</p>
          )}
      </div>
    </div>
  </div>
  );
}
